package queue
import("context";"errors";"fmt";"testing";"time")
func TestCapacityFIFOAndMiddleCancellation(t *testing.T){q:=New(20);defer q.Close();now:=time.Now();_,active,err:=q.Admit(context.Background(),"active",now);if err!=nil||!active{t.Fatal("first request not active")};for i:=range 20{_,a,e:=q.Admit(context.Background(),fmt.Sprintf("w%02d",i),now.Add(time.Duration(i)*time.Millisecond));if e!=nil||a{t.Fatalf("waiting %d not admitted",i)}};if _,_,e:=q.Admit(context.Background(),"overflow",now);e!=ErrFull{t.Fatalf("overflow=%v",e)};if e:=q.Cancel("w10",Cancelled);e!=nil{t.Fatal(e)};next:=q.CompleteActive(now);if next==nil||next.ID!="w00"{t.Fatalf("first promotion=%v",next)};s:=q.Snapshot();for _,e:=range s.Waiting{if e.ID=="w10"{t.Fatal("cancelled entry remained")}}}
func TestExpiredHeadNeverPromotes(t *testing.T){q:=New(20);defer q.Close();now:=time.Now().Add(-31*time.Minute);q.Admit(context.Background(),"active",now);e,_,_:=q.Admit(context.Background(),"expired",now);q.CompleteActive(time.Now());if got:=e.Wait(context.Background());got!=TimedOut{t.Fatalf("got %s",got)}}
func TestCancelPersistenceFailureInterruptsAllWaiting(t *testing.T){q:=New(20);defer q.Close();now:=time.Now();_,_,_ = q.Admit(context.Background(),"active",now);first,_,_:=q.Admit(context.Background(),"first",now);second,_,_:=q.Admit(context.Background(),"second",now);persistErr:=errors.New("database unavailable");if err:=q.CancelWith("first",Cancelled,func(*Entry)error{return persistErr});!errors.Is(err,persistErr){t.Fatalf("cancel error = %v",err)};if got:=first.Wait(context.Background());got!=Interrupted{t.Fatalf("first result = %s",got)};if got:=second.Wait(context.Background());got!=Interrupted{t.Fatalf("second result = %s",got)};if snap:=q.Snapshot();len(snap.Waiting)!=0{t.Fatalf("waiting survived uncertain persistence: %#v",snap.Waiting)}}
func TestPromotionPersistenceFailureCannotPromoteLaterEntry(t *testing.T){q:=New(20);defer q.Close();now:=time.Now();_,_,_ = q.Admit(context.Background(),"active",now);first,_,_:=q.Admit(context.Background(),"first",now);second,_,_:=q.Admit(context.Background(),"second",now);persistErr:=errors.New("database unavailable");next,err:=q.CompleteActiveWith(now,func(*Entry)error{return persistErr});if next!=nil||!errors.Is(err,persistErr){t.Fatalf("promotion = %v, error = %v",next,err)};if got:=first.Wait(context.Background());got!=Interrupted{t.Fatalf("first result = %s",got)};if got:=second.Wait(context.Background());got!=Interrupted{t.Fatalf("second result = %s",got)};snap:=q.Snapshot();if snap.ActiveID!=""||len(snap.Waiting)!=0{t.Fatalf("queue survived uncertain persistence: %#v",snap)}}
func TestDrainPersistenceFailureSignalsInterrupted(t *testing.T){q:=New(20);defer q.Close();now:=time.Now();_,_,_ = q.Admit(context.Background(),"active",now);waiting,_,_:=q.Admit(context.Background(),"waiting",now);persistErr:=errors.New("database unavailable");_,_,err:=q.DrainWith(Stopped,func(*Entry,bool)error{return persistErr});if !errors.Is(err,persistErr){t.Fatalf("drain error = %v",err)};if got:=waiting.Wait(context.Background());got!=Interrupted{t.Fatalf("waiting result = %s",got)};snap:=q.Snapshot();if snap.ActiveID!=""||len(snap.Waiting)!=0{t.Fatalf("queue survived uncertain drain: %#v",snap)}}
func TestTimeoutPersistenceFailurePreventsLaterPromotion(t *testing.T){q:=New(20);defer q.Close();now:=time.Now();_,_,_ = q.Admit(context.Background(),"active",now);persistErr:=errors.New("database unavailable");expired,_,_:=q.AdmitDurable(context.Background(),"expired",now,func(*Entry,bool)error{return nil},func(*Entry)error{return persistErr},nil);expired.Deadline=now.Add(-time.Second);later,_,_:=q.Admit(context.Background(),"later",now);next,err:=q.CompleteActiveWith(now,func(*Entry)error{return nil});if next!=nil||!errors.Is(err,persistErr){t.Fatalf("promotion = %v, error = %v",next,err)};if got:=expired.Wait(context.Background());got!=PersistenceFailed{t.Fatalf("expired result = %s",got)};if got:=later.Wait(context.Background());got!=Interrupted{t.Fatalf("later result = %s",got)};snap:=q.Snapshot();if snap.ActiveID!=""||len(snap.Waiting)!=0{t.Fatalf("queue survived uncertain timeout: %#v",snap)}}
func TestCancelledWaiterPersistsBeforeNextPromotion(t *testing.T){q:=New(20);defer q.Close();now:=time.Now();_,_,_ = q.Admit(context.Background(),"active",now);ctx,cancel:=context.WithCancel(context.Background());cancel();cancelled,_,_:=q.AdmitDurable(ctx,"cancelled",now,func(*Entry,bool)error{return nil},nil,func(*Entry)error{return nil});later,_,_:=q.Admit(context.Background(),"later",now);next,err:=q.CompleteActiveWith(now,func(*Entry)error{return nil});if err!=nil||next==nil||next.ID!="later"{t.Fatalf("promotion = %v, error = %v",next,err)};if got:=cancelled.Wait(context.Background());got!=CancelledPersisted{t.Fatalf("cancelled result = %s",got)};if got:=later.Wait(context.Background());got!=Promoted{t.Fatalf("later result = %s",got)}}
func TestCancelledWaiterPersistenceFailurePreventsPromotion(t *testing.T){q:=New(20);defer q.Close();now:=time.Now();_,_,_ = q.Admit(context.Background(),"active",now);ctx,cancel:=context.WithCancel(context.Background());cancel();persistErr:=errors.New("database unavailable");cancelled,_,_:=q.AdmitDurable(ctx,"cancelled",now,func(*Entry,bool)error{return nil},nil,func(*Entry)error{return persistErr});later,_,_:=q.Admit(context.Background(),"later",now);next,err:=q.CompleteActiveWith(now,func(*Entry)error{return nil});if next!=nil||!errors.Is(err,persistErr){t.Fatalf("promotion = %v, error = %v",next,err)};if got:=cancelled.Wait(context.Background());got!=PersistenceFailed{t.Fatalf("cancelled result = %s",got)};if got:=later.Wait(context.Background());got!=Interrupted{t.Fatalf("later result = %s",got)}}
